public class SafelistTest {
    private Safelist underTest;
    private Safelist none;
    private Safelist simpleText;
    private Safelist basic;
    private Safelist basicWithImages;
    private Safelist relaxed;

    @Before
    public void setup() {
        this.none = Safelist.none();
        this.simpleText = Safelist.simpleText();
        this.basic = Safelist.basic();
        this.basicWithImages = Safelist.basicWithImages();
        this.relativelySafe = new Safelist(); // placeholder for relaxes
    }

    @Test
    public void none_test() {
        assertEquals(false, underTest.isSafeTag("tag"));
    }

    @Test
    public void simpleText_test() {
        assertEquals(true, underTest.isSafeTag("text")); // no special handling needed
    }

    @Test
    public void basic_text_no_tags() {
        Element element = none().addTags("", "class");
        assertEquals(0, underTest.getEnforcedAttributes("tag").size()); // should be empty
    }

    @Test
    public void basic_text_tags() {
        Element element = basic().addTags("a", "title");
        assertEquals(1, underTest.getEnforcedAttributes("tag").size());
        for (String tag : new String[]{"a", "title"}){
            assertEquals("a", underTest.getEnforcedAttributes(tag).get(0).toString());
        }
    }

    @Test
    public void basic_text_with_images() {
        Element element = basicWithImages().addTags("", "class");
        assertEquals(1, underTest.getEnforcedAttributes("tag").size()); // should be empty
        for (String tag : new String[]{"a", "img"}){
            assertEquals("img", underTest.getEnforcedAttributes(tag).get(0).toString());
        }
    }

    @Test
    public void relaxed_text_no_tags() {
        Safelist relaxes = new Relaxed();
        Element element = none().addTags("", "class");
        element.addAttributes(relaxes.addAttribute("rel", "", ""));
        assertEquals(true, underTest.isSafeTag("text"));
    }

    @Test
    public void relaxed_text_tags_with_relaxes() {
        Safelist relaxes = new Relaxed();
        Element element = basic().addTags("", "class");
        element.addAttributes(relaxes.addAttribute("rel", "", ""));
        assertEquals(true, underTest.isSafeTag("text"));
    }

    @Test
    public void relaxed_text_with_relaxes_no_tags() {
        Safelist relaxes = new Relaxed();
        Element element = none().addTags("", "class");
        element.addAttributes(relaxes.addAttribute("rel", "", ""));
        assertEquals(true, underTest.isSafeTag("text"));
    }

    @Test
    public void none_tag_is_safe() {
        assertEquals(false, underTest.isSafeTag("tag"));
    }
}

